def parse(tree):
    # nodes are numbered in the order they appear in the array; a child always gets a larger number than its parent
    if not tree:
        return [], [], []
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def minSwapsToBst(tree):
    val, left, right = parse(tree)
    n = len(val)
    order = []
    stack = []
    u = 0
    while stack or u != -1:
        while u != -1:
            stack.append(u)
            u = left[u]
        u = stack.pop()
        order.append(val[u])
        u = right[u]
    rank = {v: i for i, v in enumerate(sorted(order))}
    target = [rank[v] for v in order]   # where the element at position i has to go
    seen = [False] * n
    cycles = 0
    for i in range(n):
        if not seen[i]:
            cycles += 1
            j = i
            while not seen[j]:
                seen[j] = True
                j = target[j]
    return n - cycles
